#ifndef INSTRUCTION_HPP
#define INSTRUCTION_HPP

#include <utility>
#include "Common.h"
#include <string>
#include <iostream>

typedef unsigned int Instruction;

class InstructionBase {
public:
    enum Type { R, I, S, B, U, J };

    Instruction opcode;
    Instruction rs1;
    Instruction rs2;
    Instruction rd;
    Instruction funct3;
    Instruction funct7;
    int imm;
    Instruction inst;
    Type t;

    InstructionBase() : opcode(0), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(0), t(R) {}

    InstructionBase(Type type) : opcode(0), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(-1), inst(-1), t(type) {}

    static InstructionBase nop() {
        return InstructionBase();
    }

    static int bin_mask(int digits) {
        return (1 << digits) - 1;
    }

    static int get_digits(unsigned int n, int hi, int lo) {
        return (n >> lo) & bin_mask(hi - lo + 1);
    }

    static int expand_digit(unsigned int digit, int lo) {
        if ((digit >> (lo - 1)) & 1)
            return digit | (~bin_mask(lo));
        else
            return digit;
    }

    bool is_nop() const {
        return inst == 0;
    }

    bool is_valid(const std::string &key) const {
        if (key == "opcode") return opcode != 0;
        if (key == "rs1") return rs1 >= 0 && rs1 < 32;
        if (key == "rs2") return rs2 >= 0 && rs2 < 32;
        if (key == "rd") return rd >= 0 && rd < 32;
        if (key == "funct3") return funct3 >= 0 && funct3 < 8;
        if (key == "funct7") return funct7 >= 0 && funct7 < 128;
        if (key == "imm") return true; // imm can be any value
        return false;
    }

    void verify(const std::string &key) const {
        if (!is_valid(key))
            throw InvalidAccess("Invalid access to field: " + key);
    }

    void debug() const {
        std::cout << "InstructionBase - opcode: " << opcode << ", rs1: " << rs1 << ", rs2: " << rs2 << ", rd: " << rd << ", funct3: " << funct3 << ", funct7: " << funct7 << ", imm: " << imm << std::endl;
    }

    bool has_op1() const {
        return t == R || t == I || t == S || t == B;
    }

    bool has_op2() const {
        return t == R || t == S || t == B;
    }

    class InvalidAccess : public std::exception {
    private:
        std::string msg;
    public:
        InvalidAccess(const std::string &message) : msg(message) {}
        const char* what() const noexcept override {
            return msg.c_str();
        }
    };
};

class InstructionR : public InstructionBase {
public:
    InstructionR(Instruction inst) : InstructionBase(R) {
        this->inst = inst;
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 11, 7);
        rs2 = get_digits(inst, 19, 15);
        rd = get_digits(inst, 24, 20);
        funct3 = get_digits(inst, 14, 12);
        funct7 = get_digits(inst, 31, 25);
    }
};

class InstructionI : public InstructionBase {
public:
    InstructionI(Instruction inst) : InstructionBase(I) {
        this->inst = inst;
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 19, 15);
        rd = get_digits(inst, 11, 7);
        funct3 = get_digits(inst, 14, 12);
        imm = expand_digit(get_digits(inst, 31, 20), 12);
    }
};

class InstructionS : public InstructionBase {
public:
    InstructionS(Instruction inst) : InstructionBase(S) {
        this->inst = inst;
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        funct3 = get_digits(inst, 14, 12);
        imm = expand_digit(get_digits(inst, 7, 7) << 5 | get_digits(inst, 11, 8), 12);
    }
};

class InstructionB : public InstructionBase {
public:
    InstructionB(Instruction inst) : InstructionBase(B) {
        this->inst = inst;
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        funct3 = get_digits(inst, 14, 12);
        imm = expand_digit(get_digits(inst, 7, 7) << 11 | get_digits(inst, 12, 8) << 6 | get_digits(inst, 30, 25) << 1 | get_digits(inst, 31, 31) << 12, 13);
    }
};

class InstructionU : public InstructionBase {
public:
    InstructionU(Instruction inst) : InstructionBase(U) {
        this->inst = inst;
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        imm = expand_digit(get_digits(inst, 31, 12) << 12, 20);
    }
};

class InstructionJ : public InstructionBase {
public:
    InstructionJ(Instruction inst) : InstructionBase(J) {
        this->inst = inst;
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        imm = expand_digit(get_digits(inst, 20, 20) << 11 | get_digits(inst, 30, 25) << 6 | get_digits(inst, 24, 21) << 1 | get_digits(inst, 31, 31) << 20, 21);
    }
};

#endif // INSTRUCTION_HPP
